WITH latest AS (SELECT * FROM promotions QUALIFY ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY starts_on DESC, id) = 1) SELECT CASE WHEN discount_pct >= 0.27 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_tier, COUNT(*) AS num_rows, COUNT(CASE WHEN channel = 'web' THEN 1 END) AS web_count, COUNT(CASE WHEN promo_code = 'WELCOME5' THEN 1 END) AS welcome5_count, MAX(discount_pct) AS max_discount_pct, AVG(discount_pct) AS avg_discount_pct FROM latest GROUP BY ROLLUP (CASE WHEN discount_pct >= 0.27 THEN 'PREMIUM' ELSE 'STANDARD' END);
